SELECT count(*)::int AS source_rows, count(*) FILTER(WHERE cup IS NULL OR btrim(cup)='')::int AS without_cup, count(DISTINCT upper(btrim(cup))) FILTER(WHERE cup IS NOT NULL AND btrim(cup)<>'')::int AS distinct_nonempty_cup, (SELECT count(*)::int FROM (SELECT upper(btrim(cup)) FROM public.attuazione_pnrr_projects WHERE cup IS NOT NULL AND btrim(cup)<>'' GROUP BY upper(btrim(cup)) HAVING count(*)>1) d) AS repeated_cup_groups FROM public.attuazione_pnrr_projects;
